-- ============================================================
-- 004_branches_real.sql — 45개 지점 실데이터 + 요일 차등 요금
--
-- 운영관리 총괄표(2026.8.15) 01·02·03 시트에서 추출했습니다.
--   · 요금: 02 시트의 낮/밤 요금 (월~목 기준가 + 금/토/일 차등)
--   · 시설·주차·이용안내: 03 시트의 공개 가능 항목만
--   · 도어락 비밀번호 · 와이파이 · 점주 연락처는 담지 않았습니다
--     (호스트 센터 영역 — 고객 화면에 노출되면 안 되는 정보)
--
-- 실행 순서: 003_final.sql 을 먼저 실행한 뒤 이 파일을 실행합니다.
-- 이미 있는 지점(code 중복)은 건너뛰므로, 호스트 센터에서
-- 먼저 입력한 지점 데이터를 덮어쓰지 않습니다.
-- ============================================================

-- 요일 차등 요금 · 지점별 보증금 (기획서 3.2절 1단계 — 요일 차등 표준가)
ALTER TABLE branches ADD COLUMN price_rules TEXT;   -- {"day":{"base":70000,"sat":90000},...}
ALTER TABLE branches ADD COLUMN deposit INTEGER;    -- 지점별 보증금. 비우면 전사 기본(8만원)

-- 검수용 샘플 지점(강남·홍대·과천) 제거 — 예약이 붙어 있으면 남겨둡니다
DELETE FROM branches
 WHERE code IN ('GN01','HD01','GC01')
   AND id NOT IN (SELECT DISTINCT branch_id FROM reservations);

